-- 66 Puppet Theatre: the whole play is the `timeline` on this entity -
-- curtains, actors, sun and moon, backdrops, lights and captions are its
-- tracks. Its event keys call this script: `on_thunder` shakes the stage,
-- `on_applause` throws confetti. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/66-puppet-theatre.scene"
local captions, playing = true, true
local confetti = {}
local status

function init(entity)
    for i = 0, 2 do confetti[#confetti + 1] = Entity.find_by_name("Confetti" .. i) end
    status = Entity.find_by_name("Status")
end

function on_thunder(entity)
    Camera.shake(7, 0.35, 18)
end

function on_applause(entity)
    for _, c in ipairs(confetti) do
        if c then Particles.emit_burst(c, 70) end
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then
        playing = not playing
        Timeline.set(entity, "playing", playing)
    end
    if Input.is_key_just_pressed("R") then
        playing = true
        Timeline.set(entity, "clip", "play")
    end
    if status then UI.set_text(status, playing and "" or "paused") end
end
